"""Involute pinion + straight-flank rack profile generators (2D sketches, XY plane)."""

from math import ceil, pi, cos, sin, tan, acos, degrees, hypot, radians

from build123d import (Circle, GeomType, Part, Polyline, Pos, Rot, Solid,
                        extrude, make_face)

_CACHE = {}


def pinion_profile(module, teeth, pressure_angle=20.0, shift=0.0, backlash=0.0,
                   cutter_addendum=1.35, span=1.5, steps=81, simplify_tol=0.01):
    """Spur pinion generated by rolling the mating rack cutter over a blank.

    Generating the tooth form instead of drawing a bare involute gives the
    correct trochoidal root, which matters here: at 8 teeth the flank runs well
    below the base circle and a naive involute+radial root fouls the rack tips.

    `shift` is the profile-shift coefficient (avoids undercut at this tooth
    count), `backlash` thickens the cutter so the finished tooth is that much
    thinner than the space it runs in.  Rotation 0 puts a tooth space at -90
    deg, i.e. a rack tooth centred under the pinion axis.

    The sweep has to run well past one pitch (`span`) or the tooth *tips* are
    never trimmed and they foul the rack flanks; +/-1.5 pitches converges.
    """
    key = (module, teeth, pressure_angle, shift, backlash, cutter_addendum,
           span, steps, simplify_tol)
    if key in _CACHE:
        return _CACHE[key]
    m, z = module, teeth
    p = pi * m
    rp = m * z / 2
    ra = rp + m * (1.0 + shift)
    # a single cutter tooth swept over one pitch tiles the circumference exactly
    cutter, _, _ = rack_teeth(m, -0.01, 0.01, pressure_angle,
                              backlash=-backlash, addendum=cutter_addendum,
                              dedendum=1.0)
    cuts = None
    for i in range(steps):
        t = (-span + 2 * span * i / (steps - 1)) * p
        # cutter advancing +t is the pinion rolling backwards along it
        c = Rot(0, 0, -degrees(t / rp)) * (Pos(t, -(rp + shift * m)) * cutter)
        cuts = c if cuts is None else cuts + c
    gear = Circle(ra)
    for k in range(z):
        gear -= Rot(0, 0, 360.0 * k / z) * cuts
    if simplify_tol:
        gear = simplify(gear, simplify_tol)
    _CACHE[key] = gear
    return gear


def involute_profile(module, teeth, pressure_angle=20.0, shift=0.0, backlash=0.0, pts=9):
    """Plain involute form, kept for reference/comparison."""
    m, z, a = module, teeth, radians(pressure_angle)
    rp = m * z / 2.0
    rb = rp * cos(a)
    ra = rp + m * (1.0 + shift)
    rf = rp - m * (1.25 - shift)
    s = m * (pi / 2 + 2 * shift * tan(a)) - backlash

    def inv(t):
        return tan(t) - t

    def psi(r):
        return s / (2 * rp) + inv(a) - inv(acos(min(1.0, rb / r)))

    r0 = max(rb, rf) * (1 + 1e-9)
    flank = []
    if rf < rb:  # below the base circle the flank runs radially inward
        flank.append((rf * cos(psi(r0)), rf * sin(psi(r0))))
    for i in range(pts):
        r = r0 + (ra - r0) * i / (pts - 1)
        flank.append((r * cos(psi(r)), r * sin(psi(r))))

    r_in, th_in = max(0.25, rf - 0.5), psi(r0)
    poly = (
        [(r_in * cos(th_in), r_in * sin(th_in))]
        + flank
        + [(x, -y) for x, y in reversed(flank)]
        + [(r_in * cos(th_in), -r_in * sin(th_in))]
    )
    tooth = make_face(Polyline(*poly, close=True))

    gear = Circle(rf)
    for i in range(z):
        gear += Rot(0, 0, i * 360.0 / z) * tooth
    return gear


def rack_teeth(module, x_start, x_end, pressure_angle=20.0, backlash=0.0,
               addendum=1.0, dedendum=1.4, flip=False):
    """Rack teeth, reference line on y = 0, tips up (or down with flip=True).
    Teeth sit on multiples of the circular pitch so the phase is independent
    of where the rack is cut."""
    a = radians(pressure_angle)
    p = pi * module
    ha, hf = addendum * module, dedendum * module
    wa = p / 4 - ha * tan(a) - backlash / 2
    wb = p / 4 + hf * tan(a) - backlash / 2

    sk = None
    k = int(x_start / p) - 1
    while k * p <= x_end:
        xc = k * p
        k += 1
        if xc < x_start or xc > x_end:
            continue
        pts = [(xc - wb, -hf), (xc - wa, ha),
               (xc + wa, ha), (xc + wb, -hf)]
        if flip:                               # tips down, same winding
            pts = [(x, -y) for x, y in reversed(pts)]
        t = make_face(Polyline(*pts, close=True))
        sk = t if sk is None else sk + t
    return sk, hf, ha


def _chain(wire):
    """Walk a wire's edges end to end, yielding (edge, reversed).

    build123d's Wire.order_edges() compares every edge with every other, which
    on the ~1800-edge outline the rack generator produces costs 20 seconds -
    more than the rest of the pinion put together.  Hashing the endpoints does
    the same job in one pass.
    """
    edges = wire.edges()
    if len(edges) < 2:
        return [(e, False) for e in edges]

    def key(vertex):
        return (round(vertex.X, 6), round(vertex.Y, 6), round(vertex.Z, 6))

    ends = {}
    for i, edge in enumerate(edges):
        verts = edge.vertices()
        for k in (key(verts[0]), key(verts[-1])):
            ends.setdefault(k, []).append(i)

    order, used = [], set()
    verts = edges[0].vertices()
    at = key(verts[-1])
    order.append((edges[0], False))
    used.add(0)
    while len(used) < len(edges):
        nxt = next((i for i in ends.get(at, ()) if i not in used), None)
        if nxt is None:                        # not a simple closed loop
            return [(e, False) for e in wire.order_edges()]
        verts = edges[nxt].vertices()
        first, last = key(verts[0]), key(verts[-1])
        flip = first != at
        order.append((edges[nxt], flip))
        used.add(nxt)
        at = first if flip else last
    return order


def simplify(sketch, tol=0.005, arc_step=0.15):
    """Collapse a boolean-generated outline to a sparse polygon.

    Rolling the rack over the blank leaves a boundary of ~1800 hair-thin
    segments.  Extruded straight that is merely untidy, but each segment of a
    *twisted* extrusion becomes its own swept BSpline face that the mesher
    subdivides hundreds of times - a 10-tooth pinion came out as a 67 MB STL.
    Douglas-Peucker at a few microns takes it to ~240 segments and 0.8 MB,
    thinning the flanks by at most `tol` (which the mesh preload takes up
    anyway).

    The outline is read by walking the wire's own edges.  Sampling it
    parametrically instead (`wire @ t`) has to locate the edge for every
    parameter, which on a wire this long costs more than the whole rest of the
    model put together.
    """
    pts = []
    for edge, flip in _chain(sketch.faces()[0].outer_wire()):
        if edge.geom_type == GeomType.LINE:
            span = [edge @ 0, edge @ 1]
        else:                                  # the blank's tip arcs
            n = max(2, ceil(edge.length / arc_step))
            span = [edge @ (i / n) for i in range(n + 1)]
        if flip:
            span.reverse()
        pts.extend(span if not pts else span[1:])

    # drop coincident points: a zero-length segment is not a valid edge
    clean, eps = [], 1e-7
    for p in ((p.X, p.Y) for p in pts):
        if not clean or hypot(p[0] - clean[-1][0], p[1] - clean[-1][1]) > eps:
            clean.append(p)
    if len(clean) > 1 and hypot(clean[0][0] - clean[-1][0],
                                clean[0][1] - clean[-1][1]) <= eps:
        clean.pop()                            # Polyline(close=True) closes it
    pts = clean

    keep = {0, len(pts) - 1}
    stack = [(0, len(pts) - 1)]
    while stack:
        a, b = stack.pop()
        if b <= a + 1:
            continue
        (x1, y1), (x2, y2) = pts[a], pts[b]
        dx, dy = x2 - x1, y2 - y1
        span_len = hypot(dx, dy) or 1e-12
        worst, worst_i = 0.0, None
        for i in range(a + 1, b):
            x, y = pts[i]
            d = abs(dy * x - dx * y + x2 * y1 - y2 * x1) / span_len
            if d > worst:
                worst, worst_i = d, i
        if worst > tol:
            keep.add(worst_i)
            stack += [(a, worst_i), (worst_i, b)]
    return make_face(Polyline(*[pts[i] for i in sorted(keep)], close=True))


def helical_half(profile, z0, height, twist, base_twist=0.0):
    """One helical layer: `profile` extruded `height` in +Z while rotating
    `twist` degrees, starting rotated by `base_twist`."""
    face = (Rot(0, 0, base_twist) * profile).faces()[0]
    solid = Solid.extrude_linear_with_rotation(face, (0, 0, 0), (0, 0, height),
                                               twist)
    return Pos(0, 0, z0) * solid


def herringbone_pinion(profile, z0, height, twist):
    """Two opposed helical halves meeting in a chevron at mid height.  Both
    ends are rotated +twist relative to the apex, matching a rack whose teeth
    step +dx at both ends."""
    hh = height / 2
    lower = helical_half(profile, z0, hh, -twist, base_twist=twist)
    upper = helical_half(profile, z0 + hh, hh, twist)
    # the halves meet on one coincident plane, which is exactly what glue is for
    return (Part() + lower).fuse(Part() + upper, glue=True).clean()


def herringbone_rack(sketch, z0, height, dx, top_extra=0.0):
    """Rack teeth swept as a chevron: both ends offset +dx in X from the apex
    at mid height.  `top_extra` extends the UPPER half past `z0 + height`
    (same slant direction), so the top half can fill a gap above the strip
    while the bottom half stays unchanged."""
    hh = height / 2
    slant = (dx ** 2 + hh ** 2) ** 0.5
    lower = Pos(dx, 0, z0) * extrude(sketch, amount=slant, dir=(-dx, 0, hh))
    # the upper half keeps the same slant direction (dx per hh in x), only
    # longer: it lands top_extra higher AND dx * top_extra / hh further in +x
    stretch = (hh + top_extra) / hh
    upper = Pos(0, 0, z0 + hh) * extrude(
        sketch, amount=slant * stretch, dir=(dx, 0, hh))
    return lower.fuse(upper, glue=True).clean()
